import re

ROUTES = []   # (method, regex, handler)

def route(method, pattern):
    regex = re.compile("^" + re.sub(r"<(\w+)>", r"(?P<\1>[^/]+)", pattern) + "$")
    def register(handler):
        ROUTES.append((method, regex, handler))
        return handler
    return register

@route("GET", "/users/<name>/orders/<order_id>")
def user_order(request, name, order_id):
    return {"status": 200, "body": f"{name}'s order {order_id}"}

def dispatch(request):
    for method, regex, handler in ROUTES:
        m = regex.match(request["path"])
        if m and method == request["method"]:
            return handler(request, **m.groupdict())
    return {"status": 404, "body": "not found"}

for path in ["/users/riya/orders/42", "/users/riya/orders", "/users/riya/orders/42/items"]:
    print(path, "->", dispatch({"method": "GET", "path": path}))

