import json

MENU = {"dosa": 90, "idli": 50, "chai": 20}
ORDERS = []

def json_response(data, status=200):
    return {"status": status, "body": json.dumps(data)}

def create_order(request):
    body = request.get("body") or {}
    item, qty = body.get("item"), body.get("qty")
    if item not in MENU:
        return json_response({"error": f"unknown item {item!r}"}, 400)
    if not isinstance(qty, int) or not 1 <= qty <= 20:
        return json_response({"error": "qty must be a whole number from 1 to 20"}, 400)
    order = {"id": len(ORDERS) + 1, "item": item, "qty": qty, "total": MENU[item] * qty}
    ORDERS.append(order)
    return json_response(order, 201)

print(create_order({"method": "POST", "path": "/orders", "body": {"item": "dosa", "qty": 2}}))

