from wsgiref.util import setup_testing_defaults

def app(environ, start_response):
    if environ["REQUEST_METHOD"] == "GET":
        query = parse_qs(environ.get("QUERY_STRING", ""))
        data = {"search": query.get("q", [""])[0]}
