import json
from wsgiref.util import setup_testing_defaults

MENU = {"dosa": 90, "idli": 50, "chai": 20}

def respond(start_response, status, data):
    start_response(status, [("Content-Type", "application/json")])
    return [json.dumps(data).encode("utf-8")]

def app(environ, start_response):
    method, path = environ["REQUEST_METHOD"], environ["PATH_INFO"]
    parts = path.strip("/").split("/")
    if parts[0] != "menu" or len(parts) > 2:
        return respond(start_response, "404 Not Found", {"error": "not found"})
    if method != "GET":
        return respond(start_response, "405 Method Not Allowed", {"error": "method not allowed"})
    if len(parts) == 1:
        return respond(start_response, "200 OK", MENU)
    name = parts[1]
    if name not in MENU:
        return respond(start_response, "404 Not Found", {"error": f"no item {name!r}"})
    return respond(start_response, "200 OK", {"item": name, "price": MENU[name]})

env = {"REQUEST_METHOD": "GET", "PATH_INFO": "/menu/idli"}
setup_testing_defaults(env)
print(app(env, lambda status, headers: print(status)))

